<?php
require_once __DIR__.'/includes/functions.php';require_role(['recipient','charity']);expire_donations($pdo);$q=$pdo->prepare('SELECT r.*,d.food_name,d.unit,d.locality,d.expiry_at,d.status donation_status FROM collection_requests r JOIN food_donations d ON d.id=r.donation_id WHERE r.recipient_id=? ORDER BY r.requested_at DESC');$q->execute([current_user()['id']]);$requests=$q->fetchAll();$page_title='My collection requests | SharePlate';require __DIR__.'/includes/header.php';?>
<section class="page-hero compact"><div class="container"><p class="eyebrow">Keep track of pickups</p><h1>My requests</h1><p>See which donors have confirmed your collection requests.</p></div></section><section class="container section"><div class="request-list"><?php foreach($requests as $r):?><article class="request-card"><div class="request-main"><span class="badge badge-<?=strtolower($r['status'])?>"><?=e($r['status'])?></span><h3><?=e($r['food_name'])?> · <?=e($r['requested_quantity'])?> <?=e($r['unit'])?></h3><p><?=e($r['locality'])?> · Requested <?=e(format_datetime($r['requested_at']))?></p><?php if($r['status']==='Accepted'):?><p class="muted">Your pickup is accepted. Please coordinate directly with the donor using the listing details.</p><?php endif;?></div><a class="button button-small button-outline" href="food-details.php?id=<?=$r['donation_id']?>">View listing</a></article><?php endforeach;?></div><?php if(!$requests):?><div class="empty-state"><h2>No requests yet</h2><p>Find a nearby listing to request a collection.</p><a class="button" href="available-food.php">Find food</a></div><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>